from pathlib import Path
from datetime import datetime,timezone
from PIL import Image
import json,hashlib,subprocess
R=Path(__file__).resolve().parent
def write(name,data): (R/name).write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8')
screens=[]
for f in sorted((R/'screenshots').glob('*.jpg')):
    with Image.open(f) as im: size=im.size
    screens.append({'path':f.relative_to(R).as_posix(),'bytes':f.stat().st_size,'sha256':hashlib.sha256(f.read_bytes()).hexdigest(),'width':size[0],'height':size[1],'format':'JPEG','capture':'real browser fullPage screenshot; no image edits','visual_review':'inspected via contact sheet; no visible overlap or truncation in source image','privacy':'contains only explicitly fictitious review shipping input, unmasked' if f.name.startswith('06-') else 'no full contact/shipping input visible'})
write('screenshots/index.json',{'screenshots':screens,'count':len(screens),'executor':'Codex AI; not human review','viewport_caveat':'Actual widths vary 748/763/1264; not a claimed 1366/1920 full regression.'})
# Only remove generated bytecode within this new evidence directory, never raw captures.
removed=[]
for f in R.rglob('*.pyc'):
    if R not in f.resolve().parents: raise RuntimeError('Cache path outside review root')
    removed.append(f.relative_to(R).as_posix()); f.unlink()
write('generated-cache-cleanup.json',{'removed_generated_pyc_only':removed,'raw_evidence_removed':False})
write('stage-H.json',{'stage':'H','result':'存疑','finished':datetime.now(timezone.utc).isoformat(),'summary':'New core checks and summaries complete; human sign-off and STEP06 contract decision pending. No push or merge.','screenshots':8,'old_documents_modified':False,'product_modified':False})
(R/'stage-H.md').write_text('# 阶段 H 汇总\n\n本轮核心顺序复核、新证据/问题/范围与逐步结论已汇总。总体存疑：真人本人签署条件未满足，STEP06缺父版本400/409契约待统一。原失败、工具缺陷和补证均保留。8张截图，服务已停止、隔离datadir保留。旧代码、文档、证据、台账、Word均不改；仅本地复核分支提交，不推送、不合并。\n',encoding='utf-8')
# Rebuild summaries once after H exists, before final artifact hashing.
p=subprocess.run(['python','-X','utf8',str(R/'finalize_review.py')],capture_output=True,text=True,encoding='utf-8')
write('finalize-command-result.json',{'command':'python -X utf8 docs/evidence/2026-11-15-review/finalize_review.py','exit':p.returncode,'stdout':p.stdout,'stderr':p.stderr})
if p.returncode: raise RuntimeError('finalize failed')
paths=[f for f in R.rglob('*') if f.is_file() and f.name!='artifacts.sha256' and '__pycache__' not in f.parts]
(R/'artifacts.sha256').write_text(''.join(hashlib.sha256(f.read_bytes()).hexdigest()+'  '+f.relative_to(R).as_posix()+'\n' for f in sorted(paths)),encoding='utf-8',newline='')
print(json.dumps({'files':len(paths),'bytes':sum(f.stat().st_size for f in paths),'screenshots':len(screens)},ensure_ascii=False))
